private static string SetLockClass(string cssClass, bool locked)
{
    string css = cssClass == null ? "" : cssClass;
    css = css.Replace("empv2-inp-locked", "").Replace("empv2-inp-editable", "");
    while (css.IndexOf("  ") >= 0)
        css = css.Replace("  ", " ");
    css = css.Trim();
    if (locked)
        return (css + " empv2-inp-locked").Trim();
    return (css + " empv2-inp-editable").Trim();
}

