private static void LockInputs(Control parent)
{
    if (parent == null)
        return;

    foreach (Control child in parent.Controls)
    {
        TextBox txt = child as TextBox;
        if (txt != null)
            SetTextLock(txt, true);

        DropDownList ddl = child as DropDownList;
        if (ddl != null)
            SetDropDownLock(ddl, true);

        RadioButton rdo = child as RadioButton;
        if (rdo != null)
            rdo.Enabled = false;

        CheckBox chk = child as CheckBox;
        if (chk != null)
            chk.Enabled = false;

        RadDateTimePicker picker = child as RadDateTimePicker;
        if (picker != null)
            picker.Enabled = false;

        if (child.HasControls())
            LockInputs(child);
    }
}

