    txt.CssClass = SetLockClass(txt.CssClass, locked);
    if (locked)
        txt.Attributes["tabindex"] = "-1";
    else
        txt.Attributes.Remove("tabindex");
}

private static void SetDateLock(Telerik.Web.UI.RadDateTimePicker picker, bool locked)
{
    if (picker == null)
        return;
    picker.Enabled = !locked;
    picker.EnableTyping = !locked;
    if (picker.DateInput != null)
    {
        picker.DateInput.ReadOnly = locked;
        picker.DateInput.Enabled = !locked;
    }
    if (picker.DatePopupButton != null)
        picker.DatePopupButton.Enabled = !locked;
    picker.CssClass = SetLockClass(picker.CssClass, locked);
}

